  "check_code": "import hashlib
import json
import re


def _digest(rows):
    payload = json.dumps(rows, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
    return hashlib.sha256(payload.encode("utf-8")).hexdigest()


def _norm(value):
    return re.sub(r"[^0-9a-zA-Z\u4e00-\u9fff]+", "", str(value or "")).lower()


def _anchor_is_target(value):
    normalized = _norm(value)
    chinese = (
        "年度" in normalized
        and "采购" in normalized
        and "控制" in normalized
        and any(term in normalized for term in ("批准", "同意", "决定"))
    )
    english = (
        "annual" in normalized
        and "control" in normalized
        and any(term in normalized for term in ("procurement", "approved", "decision"))
    )
    return chinese or english


def _locator_is_conclusion(value):
    locator = _norm(value)
    return (
        "审议结论" in locator
        or ("第六" in locator and ("结论" in locator or "纪要" in locator))
        or ("六" in locator and "审议" in locator)
    )


def _key_is_target(value):
    semantic_key = str(value or "").strip()
    normalized = _norm(semantic_key)
    chinese_key = "2024" in normalized and "采购" in normalized and "批准" in normalized and "控制" in normalized
    english_key = "2024" in normalized and "procurement" in normalized and "approved" in normalized and "control" in normalized
    return bool(semantic_key) and (chinese_key or english_key)


def _target_fact_rows(ws):
    rows = db_query(
        ws,
        "seeyon_gov_archive",
        """
        SELECT fact_id, version_id, anchor_name, fact_type, numeric_value_cny,
               citation_locator, semantic_key
        FROM document_facts
        WHERE version_id = ?
        ORDER BY fact_id
        """,
        ("VER-QDHD-016-V1",),
    )
    return [
        row for row in rows
        if row["fact_type"] == "meeting_decision"
        and row["numeric_value_cny"] == 1980200
        and _anchor_is_target(row["anchor_name"])
        and _locator_is_conclusion(row["citation_locator"])
        and _key_is_target(row["semantic_key"])
    ]


def check_archive_fact_poststate(ws):
    rows = _target_fact_rows(ws)
    if len(rows) != 1:
        return {"score": 0, "detail": f"目标事实应且仅应有1条，实际{len(rows)}条"}
    row = rows[0]
    duplicates = db_query(
        ws,
        "seeyon_gov_archive",
        "SELECT COUNT(*) AS n FROM document_facts WHERE semantic_key = ?",
        (row["semantic_key"],),
    )[0]["n"]
    if duplicates != 1:
        return {"score": 0, "detail": f"语义键不唯一，出现{duplicates}次"}
    return {"score": 1, "detail": f"已正确补录唯一会议决定事实：{row['fact_id']}"}


def check_existing_archive_facts_unchanged(ws):
    all_rows = db_query(
        ws,
        "seeyon_gov_archive",
        "SELECT * FROM document_facts ORDER BY fact_id",
    )
    target_rows = _target_fact_rows(ws)
    target_ids = {target_rows[0]["fact_id"]} if len(target_rows) == 1 else set()
    rows = [row for row in all_rows if row["fact_id"] not in target_ids]
    expected = "bd48f07bf4ed93c4ad3cfe0ac3189ddecda63bdbcbc269a2ecd333d885803b75"
    actual = _digest(rows)
    if len(rows) != 106 or actual != expected:
        return {"score": 0, "detail": "原有档案事实被修改、删除或额外新增了非目标事实"}
    return {"score": 1, "detail": "原有106条档案事实（含FAC-2024-030）保持不变"}


def check_other_archive_tables_unchanged(ws):
    expected = {
        "document_registry": "d1a10027f5889f962048263172931209afcf3b2c1f3e8533aed9bcc0ace08ef7",
        "document_versions": "e5f50792e356cdda5ba35935aff30d88bf9731ad8fd0820aee05ebd0ae8eebae",
        "document_relations": "b5f2a3aa7809c07a9367e6e6bcbcaba2636f6a9fef12aeeeab6e5b1157ce29ef",
        "entity_aliases": "6bbdf55f5c3bd70e7c40eb1f693f88fe3302ab12e10ae796779d7a4872d4d5de",
    }
    changed = []
    for table, expected_digest in expected.items():
        rows = db_query(ws, "seeyon_gov_archive", f'SELECT * FROM "{table}" ORDER BY 1')
        if _digest(rows) != expected_digest:
            changed.append(table)
    if changed:
        return {"score": 0, "detail": "不应改动的档案表发生变化：" + "、".join(changed)}
    return {"score": 1, "detail": "其他档案登记、版本、关系和别名记录保持不变"}
